class Solution {
  public boolean isPossibleToRearrange(String s, String t, int k) {
    int len = s.length() / k;
    java.util.HashMap<String, Integer> cnt = new java.util.HashMap<>();
    for (int i = 0; i < s.length(); i += len) cnt.merge(s.substring(i, i + len), 1, Integer::sum);
    for (int i = 0; i < t.length(); i += len) {
      if (cnt.merge(t.substring(i, i + len), -1, Integer::sum) < 0) return false;
    }
    return true;
  }
}
